class Animal:
    def __init__(self, name):
        self.name = name
        self.sound = "..."
    def speak(self):
        return self.name + " says " + self.sound

class Dog(Animal):
    def __init__(self, name):
        super().__init__(name)
        self.sound = "woof"
    def speak(self):
        return super().speak() + "!"

class Puppy(Dog):
    def speak(self):
        return super().speak().upper()

print(*[a.speak() for a in (Animal("A"), Dog("D"), Puppy("P"))], sep=" | ")

class P:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __repr__(self):
        return f"P({self.x},{self.y})"
    def __str__(self):
        return f"<{self.x};{self.y}>"

p = P(1, 2)
print(p, [p], f"{p}", str([p]), repr(p))

class Temp:
    unit = "C"
    def __init__(self, c):
        self._c = c
    @property
    def f(self):
        return self._c * 9 / 5 + 32
    @classmethod
    def from_f(cls, f):
        return cls((f - 32) * 5 / 9)
    @staticmethod
    def is_boiling(c):
        return c >= 100

t = Temp.from_f(212)
print(t.f, t._c, Temp.is_boiling(t._c), Temp.unit)

